import{_ as a,o as t,c as i,a6 as r}from"./chunks/framework.B8j4beN0.js";const u=JSON.parse('{"title":"Build the Weather Watcher","description":"Extend the first Feluqa CLI program into a weather watcher with email alerts and a local service workflow.","frontmatter":{"sidebarTitle":"Weather Watcher","icon":"cloud-rain","title":"Build the Weather Watcher","description":"Extend the first Feluqa CLI program into a weather watcher with email alerts and a local service workflow.","summary":"Plans a staged weather-watcher CLI tutorial: start with a local deterministic forecast, add a live provider and locally stored API key, then send email alerts and run the program as a service. It describes local execution, implementation status, and how the exercise builds on the first Feluqa command.","weight":5,"tags":["feluqa","getting-started","cli","weather","service"],"date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","status":"Exploring","draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"learn/build-the-weather-watcher.md","filePath":"learn/build-the-weather-watcher.md"}'),s={name:"learn/build-the-weather-watcher.md"};function n(l,e,o,h,d,c){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="build-the-weather-watcher" tabindex="-1">Build the Weather Watcher <a class="header-anchor" href="#build-the-weather-watcher" aria-label="Permalink to &quot;Build the Weather Watcher&quot;">​</a></h1><p>The tutorial will develop the example in stages:</p><ol><li><strong>Read a forecast.</strong> Start with a deterministic local sample so the first run needs no account or network service.</li><li><strong>Fetch live weather.</strong> Add a provider adapter and put its API key in local configuration, outside source control.</li><li><strong>Detect a condition.</strong> Add a rule such as notifying when rain is forecast or the temperature crosses a configured limit.</li><li><strong>Send an email.</strong> Add a notification adapter with validated settings and clear handling for delivery failures.</li><li><strong>Observe and operate.</strong> Add structured logs, health information, and a bounded retry policy before running it unattended.</li></ol><p>The first version should run in the foreground. A later step can package it as a Linux service with a <code>systemd</code> unit, restart behavior, a dedicated service account, and an operator guide. The service should start only after its configuration and notification path have been verified.</p><h2 id="run-it-locally" tabindex="-1">Run it locally <a class="header-anchor" href="#run-it-locally" aria-label="Permalink to &quot;Run it locally&quot;">​</a></h2><p>For an application shape supported by the current CLI, the available workflow is:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feluqa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> weather-watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> weather-watch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feluqa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>This creates a web application, not the CLI weather service described above.</p><p>The project chooser and a CLI application profile need to land before the weather watcher can be followed end to end with Feluqa commands.</p><h2 id="implementation-status" tabindex="-1">Implementation status <a class="header-anchor" href="#implementation-status" aria-label="Permalink to &quot;Implementation status&quot;">​</a></h2><p>The guide can become a runnable tutorial once Feluqa supports an interactive application-type chooser, environment setup and verification, a CLI application scaffold, local configuration for external services, and a documented Linux service package. The server-plus-workstation option also needs a clear shared-module and API example. Until then, these steps are product direction rather than available commands.</p><h2 id="previous-step" tabindex="-1">Previous step <a class="header-anchor" href="#previous-step" aria-label="Permalink to &quot;Previous step&quot;">​</a></h2><p>Start with <a href="/learn/program-0-hello-cli">Program 0: Hello CLI</a>.</p><h2 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h2><p>Learn how an <a href="/get-started/starter-kits/application-profiles-and-starter-kits">application profile differs from a binary and compilation target</a>.</p>`,15)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
